  // Extract RecordID using regex BEFORE any parsing
  const recordIdMatch = raw.match(/"RecordID(?:\(Lead's company details\))?"\s*:\s*"([^"]+)"/);
  const recordId = recordIdMatch ? recordIdMatch[1] : null;

  // Fix ALL invalid escape sequences
  raw = raw
    .replace(/\\[$]/g, '$')        // Fix \$ → $
    .replace(/\\([^"\\\/bfnrtu])/g, '$1')  // Fix any other bad escapes
    .replace(/[\u0000-\u001F\u007F]/g, (char) => {
      if (char === '\n') return '\\n';
      if (char === '\r') return '\\r';
      if (char === '\t') return '\\t';
      return '';
    });

  // Try JSON.parse
  let parsedData = {};
  try {
    parsedData = JSON.parse(raw);
  } catch(e) {
    // Fallback: extract fields with regex
    const fieldNames = [
      "pain_points",
      "solutions", 
      "strategy_hooks",
      "analyzed_output",
      "Full Name"
    ];

    for (const field of fieldNames) {
      const escapedField = field.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      // Match field value - handles multiline content
      const regex = new RegExp(`"${escapedField}"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"`, 's');
      const match = raw.match(regex);
      if (match) {
        parsedData[field] = match[1]
