return items.map((item, itemIndex) => {
  try {
    // Get raw output - handle multiple possible input structures
    let raw = item.json.output || item.json.text || item.json.response || JSON.stringify(item.json);

    // Remove ```json and ``` wrappers
    raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

    // Fix ALL bad escape sequences
    raw = raw
      .replace(/\\[$]/g, '$')
      .replace(/\\([^"\\\/bfnrtu0-9])/g, '$1')
      .replace(/[\u0000-\u001F\u007F]/g, (char) => {
        if (char === '\n') return '\\n';
        if (char === '\r') return '\\r';
        if (char === '\t') return '\\t';
        return '';
      });

    // Try JSON.parse first
    let parsedData = {};
    let parseSuccess = false;

    try {
      parsedData = JSON.parse(raw);
      parseSuccess = true;
    } catch(e) {
      // JSON.parse failed, use regex fallback
    }

    if (!parseSuccess) {
      // Regex fallback - extract each field individually
      const stringFields = [
        "RecordID", "Full Name", "Profile Linkedin URL", "headline",
        "Person Location", "Company Name", "Current Position",
        "Company Description", "Company Website", "Company Domain",
        "Company AI Description", "Company Size", "Company linkedin_url",
        "qualification_status", "qualification_reason"
      ];

      for (const field of stringFields) {
        try {
          const escaped = field.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
          const regex = new RegExp(`"${escaped}"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"`, 's');
          const match = raw.match(regex);
          if (match) {
            parsedData[field] = match[1]
              .replace(/\\n/g, '\n')
              .replace(/\\t/g, '\t')
              .replace(/\\"/g, '"');
          }
        } catch(fieldError) {
          parsedData[field] = null;
        }
      }

      // Extract integers separately
      try {
        const cpMatch = raw.match(/"current_page"\s*:\s*(\d+)/);
        const npMatch = raw.match(/"next_page"\s*:\s*(\d+)/);
        if (cpMatch) parsedData["current_page"] = parseInt(cpMatch[1]);
        if (npMatch) parsedData["next_page"] = parseInt(npMatch[1]);
      } catch(e) {
        parsedData["current_page"] = null;
        parsedData["next_page"] = null;
      }
    }

    // Ensure current_page and next_page are always integers
    if (parsedData.current_page !== undefined) {
      parsedData.current_page = parseInt(parsedData.current_page) || null;
    }
    if (parsedData.next_page !== undefined) {
      parsedData.next_page = parseInt(parsedData.next_page) || null;
    }

    // Always ensure qualification_status is clean
    if (parsedData.qualification_status) {
      parsedData.qualification_status = parsedData.qualification_status.trim();
    }

    return { json: parsedData };

  } catch(fatalError) {
    // NOTHING can break this - if everything fails, return safe fallback
    return {
      json: {
        RecordID: item.json?.RecordID || null,
        "Full Name": item.json?.["Full Name"] || null,
        qualification_status: "parse_error",
        qualification_reason: "Failed to parse: " + fatalError.message,
        current_page: null,
        next_page: null,
        raw_output: String(item.json?.output || item.json?.text || '').slice(0, 500)
      }
    };
  }
});

return items.filter(item => {
  try {
    const sentDateRaw = item.json['Email Sent Date'];
    if (!sentDateRaw) return false;

    // Parse DD/MM/YYYY format
    const parts = sentDateRaw.split('/');
    const day = parseInt(parts[0]);
    const month = parseInt(parts[1]) - 1; // months are 0-indexed
    const year = parseInt(parts[2]);

    const sentDate = new Date(year, month, day);
    const today = new Date();

    // Reset time to midnight for accurate day comparison
    today.setHours(0, 0, 0, 0);
    sentDate.setHours(0, 0, 0, 0);

    const diffMs = today - sentDate;
    const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

    // Attach for reference downstream
    item.json.days_since_sent = diffDays;

    return diffDays >= 3;

  } catch(e) {
    return false;
  }
});

