  try {
    let raw = item.json.output || item.json.text || '';

    // Remove ```json wrappers
    raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

    // Fix bad escape sequences
    raw = raw
      .replace(/\\[$]/g, '$')
      .replace(/\\([^"\\\/bfnrtu0-9])/g, '$1')
      .replace(/[\u0000-\u001F\u007F]/g, (char) => {
        if (char === '\n') return '\\n';
        if (char === '\r') return '\\r';
        if (char === '\t') return '\\t';
        return '';
      });

    let parsed = {};
    try {
      parsed = JSON.parse(raw);
    } catch(e) {
      // Regex fallback
      const email1Match = raw.match(/"email_1"\s*:\s*"((?:[^"\\]|\\.)*)"/s);
      const email2Match = raw.match(/"email_2"\s*:\s*"((?:[^"\\]|\\.)*)"/s);
      const email3Match = raw.match(/"email_3"\s*:\s*"((?:[^"\\]|\\.)*)"/s);

      parsed = {
        email_1: email1Match ? email1Match[1].replace(/\\n/g, '\n') : '',
        email_2: email2Match ? email2Match[1].replace(/\\n/g, '\n') : '',
        email_3: email3Match ? email3Match[1].replace(/\\n/g, '\n') : ''
      };
    }

    // Extract subject and body from each email
    const extractEmail = (emailText) => {
      if (!emailText) return { subject: '', body: '' };

      const subjectMatch = emailText.match(/Subject:\s*(.+?)(?:\n\n|\n)/);
      const subject = subjectMatch ? subjectMatch[1].trim() : '';

      // Body is everything after "Subject: [subject]\n\n"
      const bodyStart = emailText.indexOf('\n\n');
      const body = bodyStart !== -1 ? emailText.substring(bodyStart + 2).trim() : emailText;

      return { subject, body };
    };

    const draft1 = extractEmail(parsed.email_1);
    const draft2 = extractEmail(parsed.email_2);
    const draft3 = extractEmail(parsed.email_3);

    return {
      json: {
        'Draft 1': parsed.email_1 || '',
        'Draft 2': parsed.email_2 || '',
        'Draft 3': parsed.email_3 || '',
        'Draft 1 Subject': draft1.subject,
        'Draft 1 Body': draft1.body,
        'Draft 2 Subject': draft2.subject,
        'Draft 2 Body': draft2.body,
        'Draft 3 Subject': draft3.subject,
        'Draft 3 Body': draft3.body
      }
    };

  } catch(fatalError) {
    return {
      json: {
        'Draft 1': '',
        'Draft 2': '',
        'Draft 3': '',
        error: fatalError.message,
        raw_output: String(item.json.output || '').slice(0, 500)
      }
    };
  }
});
